using Purview.Unions;

namespace Purview.Results.SourceGenerator;

// Unions generated by the real Purview.Unions generator in this project. The results generator runs against
// this project as an analyzer at the same time, so these declarations are the two-generator integration surface:
// the results generator sees only the source-visible case list, because a Roslyn generator never sees another
// generator's output.

/// <summary>A case of the typeof-list generated-union discovery union.</summary>
/// <param name="Id">The identifier.</param>
public readonly record struct DiscoveredSourceCase(int Id);

/// <summary>A second case of the typeof-list generated-union discovery union.</summary>
/// <param name="Reason">The reason.</param>
public readonly record struct DiscoveredOtherCase(string Reason);

/// <summary>
/// A union whose case list is only the <c>[GenerateUnion]</c> <c>typeof</c> list. The union generator emits
/// the <c>[Union]</c> attribute, storage, constructors and <c>TryGetValue</c> members; the results generator
/// must read the cases from the attribute instead of from that generated output.
/// </summary>
[GenerateUnion(typeof(DiscoveredSourceCase), typeof(DiscoveredOtherCase))]
[GenerateResult]
public readonly partial struct DiscoveredError;

/// <summary>A case of the factory-list generated-union discovery union.</summary>
/// <param name="Id">The identifier.</param>
public readonly record struct FactoryDiscoveredCase(int Id);

/// <summary>A second case of the factory-list generated-union discovery union.</summary>
/// <param name="Reason">The reason.</param>
public readonly record struct FactoryDiscoveredOtherCase(string Reason);

/// <summary>
/// A union whose case list is only its partial static factory signatures. The signatures are the
/// source-visible case list; the union generator emits their implementations.
/// </summary>
[GenerateUnion]
[GenerateResult]
public readonly partial struct FactoryDiscoveredError
{
	/// <summary>Creates the union from a case.</summary>
	/// <param name="value">The case value.</param>
	/// <returns>The union holding the case.</returns>
	public static partial FactoryDiscoveredError FromFactoryDiscoveredCase(FactoryDiscoveredCase value);

	/// <summary>Creates the union from a case.</summary>
	/// <param name="value">The case value.</param>
	/// <returns>The union holding the case.</returns>
	public static partial FactoryDiscoveredError FromFactoryDiscoveredOtherCase(FactoryDiscoveredOtherCase value);
}

/// <summary>A case of the provider-list generated-union discovery union.</summary>
/// <param name="Id">The identifier.</param>
public readonly record struct ProviderDiscoveredCase(int Id);

/// <summary>A second case of the provider-list generated-union discovery union.</summary>
/// <param name="Reason">The reason.</param>
public readonly record struct ProviderDiscoveredOtherCase(string Reason);

/// <summary>
/// A union whose case list is only its nested <see cref="IUnionMembers"/> provider. The provider is public and
/// nested because the C# union contract requires that shape, and its <c>Create</c> bodies delegate to the
/// generator's <c>CreateCaseN</c> methods.
/// </summary>
[GenerateUnion]
[GenerateResult]
public readonly partial struct ProviderDiscoveredError : ProviderDiscoveredError.IUnionMembers
{
	/// <summary>The union member provider the C# union contract requires.</summary>
	public interface IUnionMembers
	{
		/// <summary>Creates the union from a case.</summary>
		/// <param name="value">The case value.</param>
		/// <returns>The union holding the case.</returns>
		static ProviderDiscoveredError Create(ProviderDiscoveredCase value) => CreateCase0(value);

		/// <summary>Creates the union from a case.</summary>
		/// <param name="value">The case value.</param>
		/// <returns>The union holding the case.</returns>
		static ProviderDiscoveredError Create(ProviderDiscoveredOtherCase value) => CreateCase1(value);

		/// <summary>Gets the boxed case value.</summary>
		object? Value { get; }

		/// <summary>Gets whether the union holds a case.</summary>
		bool HasValue { get; }

		/// <summary>Gets the case value when the active case is the first case.</summary>
		/// <param name="value">The case value.</param>
		/// <returns>Whether the active case is the first case.</returns>
		bool TryGetValue(out ProviderDiscoveredCase value);

		/// <summary>Gets the case value when the active case is the second case.</summary>
		/// <param name="value">The case value.</param>
		/// <returns>Whether the active case is the second case.</returns>
		bool TryGetValue(out ProviderDiscoveredOtherCase value);
	}
}
